const gap = DateTime.fromISO('2026-03-29T02:30:00', { zone: 'Europe/Berlin' })
const before = DateTime.fromISO('2026-03-29T01:30:00', { zone: 'Europe/Berlin' })
return [gap.toISO(), before.plus({ hours: 1 }).toISO(), before.plus({ days: 1 }).toISO()]

const day = DateTime.local(2026, 10, 25, 12, { zone: 'Europe/Berlin' })
const ambiguous = DateTime.local(2026, 10, 25, 2, 30, { zone: 'Europe/Berlin' })
return [day.endOf('day').diff(day.startOf('day'), 'hours').hours, ambiguous.toISO(), ambiguous.plus({ hours: 1 }).toISO(), ambiguous.toFormat('HH:mm ZZZZ ZZZZZ')]

Settings.now = () => Date.parse('2026-03-03T10:00:00Z')
const base = DateTime.fromISO('2026-03-01T10:00:00Z')
return [base.toRelative(), base.plus({ days: 5 }).toRelative(), base.toRelative({ unit: 'hours' }), base.toRelativeCalendar(), base.plus({ days: 3 }).toRelativeCalendar(), base.toRelative({ style: 'short' }), base.minus({ months: 3 }).toRelative()]
